bad_example:
// Rust side — buffer contains a bare f32
let value: f32 = 42.0;
let buffer = device.create_buffer_init(&BufferInitDescriptor {
    label: Some("uniform"),
    contents: bytemuck::bytes_of(&value),
    usage: BufferUsages::UNIFORM,
});

// WGSL side — uniform address points to a raw scalar
// @group(0) @binding(0) var<uniform> scale: f32;
// ^^^ wgpu panics: uniform buffer must match struct layout
//     or WGSL rejects the address-of on a bare scalar.

good_example:
// Rust side — wrap in a repr(C) struct
#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct ScaleUniform {
    scale: f32,
    _pad: [f32; 3], // align to 16 bytes for uniform address space
}

let uniform = ScaleUniform { scale: 42.0, _pad: [0.0; 3] };
let buffer = device.create_buffer_init(&BufferInitDescriptor {
    label: Some("uniform"),
    contents: bytemuck::bytes_of(&uniform),
    usage: BufferUsages::UNIFORM,
});

// WGSL side — uniform address points to a struct
// struct ScaleUniform { scale: f32 };
// @group(0) @binding(0) var<uniform> uniforms: ScaleUniform;
// let s = uniforms.scale; // works correctly
